import React from "react";
import { useLocation } from "react-router-dom";
import FeaturedListings from './Resuable/FeatureListtings'
import { listings } from '../data/listings';

export default function SearchResultsPage() {
  const location = useLocation();
  const query = new URLSearchParams(location.search).get("query") || "";
  const category = new URLSearchParams(location.search).get("category") || "All";

  const filteredListings = Object.values(listings)
    .flat()
    .filter((listing) => {
      const matchesQuery = query ? listing.title.toLowerCase().includes(query.toLowerCase()) : true;
      const matchesCategory = category === "All" || Object.keys(listings).includes(category) && listings[category].includes(listing);
      return matchesQuery && matchesCategory;
    });

  return (
    <div className="container mx-auto px-4 py-6">
      <h1 className="text-3xl font-semibold text-gray-800 mb-6">Search Results for "{query}" in "{category}"</h1>
      <FeaturedListings searchQuery={query} searchCategory={category} />
    </div>
  );
}
